</style></head><body><?php include __DIR__ . '/lender_sidebar.php'; ?><main class="main-content"><section class="hero"><span class="pill">AI-ASSISTED ANALYSIS</span><h1>Revenue Trends & Estimate</h1><p>Review recorded completed rental revenue and a simple baseline estimate for the coming month.</p></section><div class="mb-3"><a class="btn btn-outline-success" href="lender_ai_insights.php"><i class="fa-solid fa-arrow-left me-2"></i>Back to AI Insights Dashboard</a></div><?php $revenueByMonth=array_fill(0,6,0.0);$revenueBookingCounts=array_fill(0,6,0);foreach($bookings as $booking){$st=strtolower(trim($booking['status']??''));if(!in_array($st,['completed','returned'],true))continue;$month=date('Y-m',strtotime((string)$booking['start_date']));$idx=array_search($month,$monthKeys,true);if($idx!==false){$revenueByMonth[$idx]+=(float)$booking['total_amount'];$revenueBookingCounts[$idx]++;}}$recent=array_slice($revenueByMonth,-3);$nonzero=array_values(array_filter($recent,static function($v){return $v>0;}));$nextEstimate=$nonzero?array_sum($nonzero)/count($nonzero):0;?>
<div class="notice"><strong>Forecast limitation:</strong> This baseline averages recent months with completed rental revenue; it is not a trained forecasting model and can be misleading with sparse or seasonal data.</div><section class="summary-grid" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr))"><div class="summary-card"><small>Total completed rental value</small><span class="summary-value"><?= money($totalRevenue) ?></span></div><div class="summary-card"><small>Completed / returned rentals</small><span class="summary-value"><?= (int)$completedBookings ?></span></div><div class="summary-card"><small>Baseline next-month estimate</small><span class="summary-value"><?= $nextEstimate>0?money($nextEstimate):'Not enough data' ?></span></div></section><section class="panel"><h2>Completed Rental Revenue — Last 6 Months</h2><div class="chart-container"><canvas id="revenueChart"></canvas></div><p class="muted mt-3">Revenue grouped by booking start month for completed/returned bookings; it may differ from settled payments or accounting records.</p></section><section class="panel"><h2>Monthly breakdown</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Month</th><th>Completed / returned rentals</th><th>Recorded rental value</th></tr></thead><tbody><?php for($i=0;$i<count($monthLabels);$i++): ?><tr><td><?= h($monthLabels[$i]) ?></td><td><?= (int)$revenueBookingCounts[$i] ?></td><td><?= money($revenueByMonth[$i]) ?></td></tr><?php endfor; ?></tbody></table></div></section><script>new Chart(document.getElementById('revenueChart'),{type:'line',data:{labels:<?= json_encode($monthLabels) ?>,datasets:[{label:'Recorded rental value (₹)',data:<?= json_encode($revenueByMonth) ?>,borderColor:'#1f8b57',backgroundColor:'rgba(31,139,87,.12)',fill:true,tension:.25}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true,ticks:{callback:v=>'₹'+v}}}}});</script></main></body></html>